const VO_KEYS=['start1','start2','start3','start4','complete1','complete2','complete3','fail1','fail2','fell','mine','tooslow','finish','low_wall','high_wall','wire','hurdles','logs','tunnel','mud','water','trench','beam','bars','mines','carry_pick','carry_drop','cargo_net','rope','weave','sprint','smoke','shoot_static','shoot_popup','shoot_moving','shoot_far','shoot_timed','shoot_noshoot','shoot_plates','shoot_cover','station_clear','reload','friendly','miss','timed_fail','r_intro','r_foot','r_util','r_pack','r_report','d_intro','d_left','d_right','d_about','d_att','c_intro','s_intro','s_buoy','s_ladder','s_breathe','p_intro','p_guard','p_counter','m_intro','x_intro','x_crate','x_help','x_summit','x_ceremony','g_intro','g_join','g_ega','g_congrats'];
const VO={};let voCur=null,voQ=[],voPreloaded=false;
function voPreload(){if(voPreloaded)return;voPreloaded=true;for(const k of VO_KEYS){const a=new Audio();a.preload='auto';a.src='vo/'+k+'.mp3';VO[k]=a;}}
function playVo(key){const a=VO[key]||(VO[key]=new Audio('vo/'+key+'.mp3'));try{a.currentTime=0;}catch{}a.volume=1;voCur=a;a.onended=()=>{voCur=null;const n=voQ.shift();if(n)playVo(n);};const p=a.play();if(p)p.catch(()=>{voCur=null;});}
function voBusy(){return voCur&&!voCur.paused&&!voCur.ended;}
function vo(key,mode2='interrupt'){if(!key||muted)return;if(mode2==='ifIdle'){if(!voBusy())playVo(key);return;}if(mode2==='queue'){if(voBusy())voQ.push(key);else playVo(key);return;}voQ=[];if(voCur){try{voCur.pause();}catch{}}playVo(key);}
function voStop(){voQ=[];if(voCur){try{voCur.pause();}catch{}voCur=null;}}
window.__vo={get current(){return voCur?voCur.src:null},get queue(){return voQ.slice()}};

function respawn(z,x=0,key='fell',msg='BACK TO THE START OF THE OBSTACLE'){const p=player.position;p.set(x,0,z);velY=0;grounded=true;player.rotation.y=0;vo(key);say(msg,'bad',1.4);tone(120,.25,'sawtooth',.06);score=Math.max(0,score-25);}
function laneAt(o,dz){const i=Math.min(o.lanes.length-1,Math.floor(dz/o.band)),f=THREE.MathUtils.clamp((dz-i*o.band)/2.2,0,1);return i===0?o.lanes[0]:THREE.MathUtils.lerp(o.lanes[i-1],o.lanes[i],f);}
function inZone(o,p){return p.z<=o.z0&&p.z>=o.z1;}
function zoneSpeed(p){let f=1;for(const o of zones)if(o.slow&&inZone(o,p))f=Math.min(f,o.slow);return f;}
function gauntletZones(p,moving){let hang=false;
 for(const o of zones){if(!inZone(o,p))continue;
  if(o.type==='pit'&&p.y<=.001){respawn(o.z0+2.2,0,'fell','YOU FELL IN THE TRENCH');return;}
  if(o.type==='beam'&&p.y<=.001&&Math.abs(p.x-o.bx)>o.hw){respawn(o.z0+1.6,o.bx,'fell','YOU FELL OFF THE BEAM');return;}
  if(o.type==='bars'){if(keys[' ']&&Math.abs(p.x)<1.3){hang=true;p.y=.55;velY=0;grounded=false;}else{respawn(o.z0+1.8,0,'fell','YOU LET GO OF THE BARS');return;}}
  if(o.type==='mines'){if(Math.abs(p.x-laneAt(o,o.z0-p.z))>o.hw){respawn(o.z0+1.6,o.lanes[0],'mine','SIMULATED MINE · STAY IN THE LANE');tone(60,.5,'sawtooth',.12);return;}}
 }
 player.userData.pose=hang?'hang':'stand';
}
function gauntletPrompt(p){for(const o of zones){if(p.z>o.z0+4.5||p.z<o.z1)continue;const t={pit:'Sprint, then Space to jump the trench',beam:'Stay on the beam',bars:'Hold Space · hang on the monkey bars',mines:'Stay between the white tape',slow:''}[o.type];if(t){$('prompt').textContent=t;$('prompt').classList.remove('hidden');}}}

