function animateTargets(dt){for(const t of gTargets){if(!t.g.visible)continue;if(t.done){t.fall=Math.min(1,t.fall+dt*4);t.g.rotation.x=-t.fall*1.45;continue;}
 if(t.kind==='moving'){const sp=station?.spec.speed??1;t.g.position.x=t.baseX*.6+Math.sin(time*sp*.7+t.phase)*3.2;}
 if(t.kind==='popup'){const up=station?.spec.up??2.4,cyc=up+1.5,ph=(time+t.phase*cyc/6)%cyc;const target=ph<up?0:-1.5;t.g.rotation.x+= (target-t.g.rotation.x)*Math.min(1,dt*10);}}}
function updateStation(dt){const st=station;if(keys.arrowleft)rangeX+=dt*.18;if(keys.arrowright)rangeX-=dt*.18;if(keys.arrowup)rangeY+=dt*.15;if(keys.arrowdown)rangeY-=dt*.15;rangeX=THREE.MathUtils.clamp(rangeX,-.42,.42);rangeY=THREE.MathUtils.clamp(rangeY,-.22,.22);
 animatePerson(player,false,time);stationCamera();const hostiles=st.c.targets.filter(t=>!t.friendly);
 if(st.reloadAt&&time>=st.reloadAt){st.reloadAt=0;st.rounds=hostiles.filter(t=>!t.done).length+st.spec.spare;say('RELOADED','good',.6);tone(420,.05,'square',.04);}
 if(edges.j&&!st.reloadAt){if(st.rounds>0){st.rounds--;tone(65,.12,'sawtooth',.17);player.userData.body.position.z=.09;const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(0,0),camera);const live=st.c.targets.filter(t=>!t.done&&!(t.kind==='popup'&&t.g.rotation.x<-.35));const hit=ray.intersectObjects(live.flatMap(t=>[t.face,t.inner]),false)[0];
  if(hit){const t=live.find(t=>t.face===hit.object||t.inner===hit.object);t.done=true;if(t.friendly){score=Math.max(0,score-150);say('FRIENDLY · CHECK YOUR TARGET','bad',1.1);vo('friendly');tone(110,.3,'sawtooth',.08);}else{st.hits++;score+=150;say(t.kind==='plates'?'DING · PLATE DOWN':'TARGET HIT','good',.5);tone(t.kind==='plates'?1200:350,.08);}}
  else{say('MISS','bad',.4);if(time-lastMissVo>7){lastMissVo=time;vo('miss','ifIdle');}}
  if(st.rounds===0&&hostiles.some(t=>!t.done)){st.reloadAt=time+1.3;score=Math.max(0,score-50);say('RELOAD','bad',1);vo('reload','ifIdle');}}}
 if(st.spec.s==='timed'&&time-st.t0>st.spec.tlimit&&hostiles.some(t=>!t.done)){for(const t of st.c.targets){t.done=false;t.fall=0;t.g.rotation.x=0;}st.hits=0;st.t0=time;st.rounds=st.spec.req+st.spec.spare;st.reloadAt=0;say('TIME · TARGETS RESET','bad',1.2);vo('timed_fail');}
 const left=hostiles.filter(t=>!t.done).length;
 $('hudObjective').textContent=STATIONS[st.spec.s].label+' · '+(hostiles.length-left)+' / '+hostiles.length+' hits · '+(st.reloadAt?'reloading':st.rounds+' rounds')+(st.spec.s==='timed'?' · '+Math.max(0,st.spec.tlimit-(time-st.t0)).toFixed(1)+'s':'');
 if(left===0){score+=200;say('STATION CLEAR','good',1);vo('station_clear');endStation();completeCheckpoint(true);}}

