function showScreen(name){document.querySelectorAll('.screen').forEach(el=>el.classList.toggle('hidden',el.id!==name));$('hud').classList.toggle('hidden',name!==null);$('touchControls').classList.toggle('playing',name===null);$('hold').classList.add('hidden');$('prompt').classList.add('hidden');}
