function brief(n){buildLevel(n);mode='brief';showScreen('brief');const l=levels[n];$('briefPhase').textContent='LEVEL '+l.num+' · '+l.phase+' · '+l.week;$('briefTitle').textContent=l.name;$('briefText').textContent=l.desc;$('briefList').innerHTML=l.tasks.map(x=>'<li>'+x+'</li>').join('');}
function begin(){mode='playing';showScreen(null);keys={};edges={};startAudio();const intro={receive:'r_intro',drill:'d_intro',course:'c_intro',swim:'s_intro',combat:'p_intro',range:'m_intro',crucible:'x_intro',grad:'g_intro'}[levels[idx].kind]||('start'+(1+idx%4));say(levels[idx].name,'',1.8);vo(intro);if(checkpoints[0]?.vo)vo(checkpoints[0].vo,'queue');}
function populateSelect(){const groups=[['FOUNDATION','Levels 1–25'],['IMMERSION','Levels 26–55'],['TRANSFORMATION','Levels 56–99'],['TRANSITION','Level 100']];$('levelGrid').innerHTML=groups.map(([ph,r])=>`<div class="phase-head"><b>${ph}</b><span>${r}</span></div>`+levels.map((l,n)=>l.phase!==ph?'':`<button class="lvl${l.milestone?' milestone':''}${records.has(n)?' cleared':''}" data-level="${n}" title="${l.name}"><span class="n">${String(n+1).padStart(2,'0')}</span><span class="t">${l.name}</span><span class="d">${l.milestone?'BOOT CAMP · '+l.week:(l.segs.filter(s=>s.t!=='shoot').length+' obstacles · '+l.segs.filter(s=>s.t==='shoot').length+' firing')}</span>${records.has(n)?'<span class="done">CLEARED</span>':''}</button>`).join('')).join('');document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>brief(+b.dataset.level));$('selectCount').textContent=records.size+' / 100 cleared';}
function say(text,cls='',duration=2){$('shout').innerHTML=text;$('shout').className='shout on '+cls;shoutUntil=time+duration;}
function finish(pass=true){if(mode!=='playing')return;if(race?.active){if(pass)race.complete();return;}mode='result';keys={};edges={};$('shout').classList.remove('on');$('hold').classList.add('hidden');if(station)endStation();if(levels[idx].kind!=='grad')vo(pass?'complete'+(1+idx%3):'fail'+(1+idx%2));if(pass){records.set(idx,{score,time});saveRecords();tone(660,.18);setTimeout(()=>tone(880,.3),150);}else tone(140,.4);
if(pass&&levels[idx].kind==='grad'){showScreen('grad');$('gradStats').innerHTML=stat('LEVELS CLEARED',records.size+'/100')+stat('TOTAL SCORE',[...records.values()].reduce((a,r)=>a+r.score,0))+stat('CEREMONY TIME',fmt(time));return;}
showScreen('result');$('resPhase').textContent=levels[idx].phase;$('resTitle').textContent=pass?'TRAINING COMPLETE':'TRY AGAIN, RECRUIT';$('resTitle').className='sheet-title '+(pass?'pass':'fail');$('resText').textContent=pass?'You met the objective. Take a breath, then prepare for the next challenge.':'You can retry this challenge. Pace yourself, watch the instructions, and keep going.';$('resStats').innerHTML=stat('TIME',fmt(time))+stat('SCORE',score)+(levels[idx].kind==='gauntlet'?stat('LEVEL',levels[idx].num+' / 100'):levels[idx].kind==='range'?stat('HITS',hits+'/6'):levels[idx].kind==='drill'?stat('COMMANDS',drillCorrect+'/8'):'');$('btnNext').classList.toggle('hidden',!pass||idx>=levels.length-1);}
function stat(k,v){return `<div class="stat"><b>${v}</b><span>${k}</span></div>`;}function fmt(t){return Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0');}
function pause(){if(war?.active){war.pause();return;}if(mode==='playing'&&race?.isOnline()){say('LIVE RACE · CLOCK KEEPS RUNNING','',1.2);return;}if(mode==='playing'){race?.setPaused(true);mode='paused';showScreen('pause');keys={};}else if(mode==='paused'){race?.setPaused(false);mode='playing';showScreen(null);keys={};}}
$('btnStart').onclick=()=>{let n=0;while(n<levels.length-1&&records.has(n))n++;brief(n);};$('btnGo').onclick=begin;$('btnSelect').onclick=()=>{populateSelect();mode='select';showScreen('select');};$('btnControls').onclick=()=>{mode='controls';showScreen('controls');};document.querySelectorAll('[data-back],[data-back-title]').forEach(b=>b.onclick=title);$('btnResume').onclick=pause;$('btnRestart').onclick=()=>race?.active?race.retry():brief(idx);$('btnRetry').onclick=()=>brief(idx);$('btnNext').onclick=()=>brief(idx+1);
function setupHud(){const l=levels[idx],k=l.kind;$('hudPhase').textContent=l.phase;$('hudLevel').textContent=l.num+' · '+l.name;$('barHealth').classList.toggle('hidden',k!=='combat');$('barEnemy').classList.toggle('hidden',k!=='combat');$('barBreath').classList.toggle('hidden',k!=='swim');$('barStamina').classList.toggle('hidden',k==='drill'||k==='range');$('crosshair').classList.toggle('hidden',k!=='range');$('c').style.cursor=k==='range'?'none':'grab';$('wind').classList.add('hidden');$('compass').classList.add('hidden');$('hudScoreLabel').textContent=k==='range'?'HITS / ROUNDS':'SCORE';const hints={receive:'<kbd>WASD</kbd> Move · <kbd>E</kbd> Interact',drill:'<kbd>A</kbd> Left · <kbd>D</kbd> Right<br><kbd>S</kbd> About · <kbd>E</kbd> Attention',course:'<kbd>Space</kbd> Jump / climb<br><kbd>C</kbd> Crawl · <kbd>Shift</kbd> Sprint',swim:'<kbd>WASD</kbd> Swim · <kbd>Space</kbd> Tread',combat:'<kbd>J</kbd> Strike · <kbd>K</kbd> Block',range:'Mouse / arrows: aim<br><kbd>J</kbd> Fire · <kbd>K</kbd> Zoom',crucible:'<kbd>Space</kbd> Jump · <kbd>C</kbd> Crawl<br><kbd>E</kbd> Collect / help',gauntlet:'<kbd>Space</kbd> Jump / climb / hang · <kbd>C</kbd> Crawl<br><kbd>E</kbd> Use · <kbd>J</kbd> Fire · <kbd>K</kbd> Zoom',grad:'<kbd>WASD</kbd> March · <kbd>E</kbd> Interact'};$('hudKeys').innerHTML=hints[k]+'<br><kbd>P</kbd> Pause · <kbd>M</kbd> Mute';}
function startAudio(){voPreload();if(sound){sound.resume();return;}try{sound=new (window.AudioContext||window.webkitAudioContext)();}catch{}}
function speak(t){if(muted||!window.speechSynthesis)return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.rate=1.15;u.pitch=.55;u.volume=.9;speechSynthesis.speak(u);}catch{}}
function tone(f,d=.08,type='triangle',volume=.08){if(!sound||muted)return;const o=sound.createOscillator(),g=sound.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(volume,sound.currentTime);g.gain.exponentialRampToValueAtTime(.001,sound.currentTime+d);o.connect(g).connect(sound.destination);o.start();o.stop(sound.currentTime+d);}
