function keyDown(k){k=k.toLowerCase();if(!keys[k])edges[k]=true;keys[k]=true;}
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright','tab'].includes(k)&&mode==='playing')e.preventDefault();if((k==='p'||k==='escape')&&!e.repeat)pause();if(k==='m'&&!e.repeat){muted=!muted;if(muted)voStop();$('audioBtn').textContent=muted?'SOUND OFF':'SOUND ON';}keyDown(k);});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{keys={};edges={};if(mode==='playing'&&!race?.isOnline())pause();});
