 setJoy(dz(ax[0]||0),dz(ax[1]||0),'pad');
 const rx=dz(ax[2]||0),ry=dz(ax[3]||0);if(aiming()){rangeX-=rx*dt*.42;rangeY-=ry*dt*.32;}else{yaw-=rx*dt*2.6;pitch=THREE.MathUtils.clamp(pitch+ry*dt*1.3,-.06,.6);}
